import * as React from 'react';
import { cx } from '../../internal/cx.js';
import { Icon } from '../../icons/Icon.js';

export type AIGeneratedLabelVariant = 'generated' | 'assisted' | 'edited';

export interface AIGeneratedLabelLabels {
  /** Content written entirely by AI. */
  generated: string;
  /** Content a person wrote with help from AI. */
  assisted: string;
  /** Content a person wrote that AI then changed. */
  edited: string;
  /** Joins the label and the model name. Default "Generated by AI with Model". */
  withModel: (label: string, model: string) => string;
}

export interface AIGeneratedLabelProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  'children'
> {
  /** How AI took part. Default `generated`. */
  variant?: AIGeneratedLabelVariant;
  /** Overrides the words for this variant. */
  label?: React.ReactNode;
  /** Default `md`. */
  size?: 'sm' | 'md';
  /** The name of the model, added after the label. */
  model?: string;
  /** Show the sparkle icon. Default true. */
  showIcon?: boolean;
  /** Translations for the built in strings. */
  labels?: Partial<AIGeneratedLabelLabels>;
}

const defaultLabels: AIGeneratedLabelLabels = {
  generated: 'Generated by AI',
  assisted: 'Written with AI',
  edited: 'Edited by AI',
  withModel: (label, model) => `${label} with ${model}`,
};

/** Marks content as written or edited by AI, in plain words beside the sparkle icon. */
export const AIGeneratedLabel = React.forwardRef<HTMLSpanElement, AIGeneratedLabelProps>(
  function AIGeneratedLabel(
    {
      variant = 'generated',
      label,
      size = 'md',
      model,
      showIcon = true,
      labels: labelsProp,
      className,
      ...props
    },
    ref,
  ) {
    const labels = { ...defaultLabels, ...labelsProp };
    const base = label ?? labels[variant];
    return (
      <span
        ref={ref}
        className={cx('st-ai-generated-label', className)}
        data-variant={variant}
        data-size={size}
        {...props}
      >
        {showIcon && (
          <Icon
            name="sparkle"
            size={size === 'sm' ? 12 : 14}
            className="st-ai-generated-label__icon"
          />
        )}
        <span className="st-ai-generated-label__text">
          {model && typeof base === 'string' ? (
            labels.withModel(base, model)
          ) : (
            <>
              {base}
              {model ? ` · ${model}` : null}
            </>
          )}
        </span>
      </span>
    );
  },
);
